"""Lossless shared two-band response vectors for directional transient assets."""
import numpy as np,lzma,time,json,hashlib
from architecture import ROOT
out=ROOT/'out/v149';out.mkdir(exist_ok=True);r={'state':'running','scope':'architecture-only lossless storage; runtime integration pending','assets':[]}
for name,period,magic in [('horizontal',10,b'TRHDIC01'),('vertical',12,b'TRVDIC01')]:
 start=time.process_time();source=ROOT/f'out/phase-fast12-v116/{name}-transients.bin';raw=source.read_bytes();assert raw[:8] in (b'TRHXZ001',b'TRVXZ001');assert int.from_bytes(raw[392:396],'little')==0;original=lzma.decompress(raw[404:]);a=np.frombuffer(original,dtype='<i2').reshape(-1,2,period).transpose(0,2,1).copy().reshape(-1,2);unique,index=np.unique(a.view('V4').ravel(),return_inverse=True);values=unique.view('<i2').reshape(-1,2);width=2 if len(unique)<=65536 else 4;codes=index.astype('<u2' if width==2 else '<u4');plain=values.tobytes()+codes.tobytes();encoded=lzma.compress(plain,preset=6,check=lzma.CHECK_CRC32);b=lzma.decompress(encoded);vu=np.frombuffer(b[:values.nbytes],dtype='<i2').reshape(-1,2);ci=np.frombuffer(b[values.nbytes:],dtype=codes.dtype);decoded=vu[ci].reshape(-1,period,2).transpose(0,2,1).copy().tobytes();assert decoded==original;dest=out/f'{name}-dictionary.bin';dest.write_bytes(magic+raw[8:404]+len(unique).to_bytes(4,'little')+width.to_bytes(4,'little')+encoded);item={'name':name,'bytes':dest.stat().st_size,'old_bytes':len(raw),'unique_vectors':len(unique),'index_bytes':width,'original_decoded_sha256':hashlib.sha256(original).hexdigest(),'asset_sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'lossless_roundtrip':True,'cpu_seconds':time.process_time()-start};r['assets'].append(item);print(json.dumps(item),flush=True);(ROOT/'reports/V149-directional-dictionaries.json').write_text(json.dumps(r,indent=2)+'\n')
r['state']='complete';(ROOT/'reports/V149-directional-dictionaries.json').write_text(json.dumps(r,indent=2)+'\n')
